import re
for f in ['/tmp/whelp.html','/tmp/wh.html']:
    try: raw=open(f,encoding='utf-8',errors='replace').read()
    except: continue
    # Intercom settings blob
    for m in re.finditer(r'window\.intercomSettings\s*=\s*(\{.*?\});',raw,re.S):
        print(f, "=>", m.group(1)[:400])
    m=re.search(r'"?app_id"?\s*:\s*"?(\w+)"?',raw)
    if m: print(f,"app_id:",m.group(1))
    for pat in [r'https://intercom\.?.*?/app-id', r'widget\.intercom\.io/widget/assets/app/:([\w:]+)']:
        mm=re.search(pat,raw)
        if mm: print(f,"intercom:",mm.group(1))
EOF

