python3 << 'EOF'
import re,html,json
raw=open('/tmp/cr.html',encoding='utf-8',errors='replace').read()
# Next.js __NEXT_DATA__
m=re.search(r'<script id="__NEXT_DATA__"[^>]*>(.*?)</script>',raw,re.S)
if m:
    try:
        d=json.loads(m.group(1))
        def walk(o,depth=0):
            if depth>5: return
            if isinstance(o,dict):
                for k,v in o.items():
                    if isinstance(v,(str,int,float)) and isinstance(v,str) and 5<len(v)<600:
                        if re.search(r'(reward|eligible|clip|earn|payout|min|threshold|%|stat|creator)',v,re.I):
                            print(k,'::',v)
                    else: walk(v,depth+1)
            elif isinstance(o,list):
                for it in o[:200]: walk(it,depth+1)
        walk(d)
    except Exception as e:
        print('json err',e)
# also meta content
for mm in re.finditer(r'<meta[^>]+(?:name|property)="(description|og:description|keywords)"[^>]+content="([^"]+)"',raw):
    print('META:',mm.group(1),'::',mm.group(2)[:600])
EOF
